gql(){return"\u0422\u0440\u0438 \u0440\u0430\u0443\u043d\u0434\u0430 \u043f\u043e \u043f\u044f\u0442\u044c \u0441\u0442\u0430\u043d\u0446\u0438\u0439, \u043a\u0430\u0436\u0434\u0430\u044f \u2014 \u043c\u0438\u043d\u0443\u0442\u0430; \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u043e\u0448\u043b\u043e \u043e\u0442 \u0441\u043b\u043e\u0432 \u0431\u043e\u0439\u0446\u0430 \u043e \u0442\u043e\u043c, \u043d\u0430 \u0447\u0442\u043e \u044d\u0442\u043e \u043f\u043e\u0445\u043e\u0436\u0435. \u0421\u0435\u043c\u043d\u0430\u0434\u0446\u0430\u0442\u044c \u043c\u0438\u043d\u0443\u0442, \u0430 \u0441\u0447\u0451\u0442 \u2014 \u0432\u0441\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u044b \u0441\u043e \u0432\u0441\u0435\u0445 \u0441\u0442\u0430\u043d\u0446\u0438\u0439, \u0441\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u0432\u043c\u0435\u0441\u0442\u0435."},
